const lessons=[{"sentences":[{"speaker":"A","text":"Hello I am calling because my train is delayed and I will arrive much later than planned.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.443125},{"speaker":"B","text":"Do not worry about the delay because these things happen when you travel by train.","position":2,"audioStartSeconds":5.643125,"audioEndSeconds":10.609458333333333},{"speaker":"A","text":"What time do you think you will finally reach the apartment tonight?","position":3,"audioStartSeconds":10.809458333333334,"audioEndSeconds":14.702},{"speaker":"A","text":"I should arrive around nine o clock if the rest of the journey goes smoothly.","position":4,"audioStartSeconds":14.902,"audioEndSeconds":19.438083333333335},{"speaker":"B","text":"That is fine although I cannot meet you personally at that hour.","position":5,"audioStartSeconds":19.638083333333334,"audioEndSeconds":23.607916666666668},{"speaker":"A","text":"How can I get the keys if you are not there to open the door?","position":6,"audioStartSeconds":23.807916666666667,"audioEndSeconds":27.390375},{"speaker":"B","text":"I will leave the keys in the secure metal box beside the front entrance.","position":7,"audioStartSeconds":27.590375,"audioEndSeconds":32.21666666666667},{"speaker":"A","text":"Is the box difficult to open or will I need a special code?","position":8,"audioStartSeconds":32.416666666666664,"audioEndSeconds":36.308416666666666},{"speaker":"B","text":"You just need the four digit code that I sent to your phone earlier.","position":9,"audioStartSeconds":36.50841666666667,"audioEndSeconds":40.670791666666666},{"speaker":"A","text":"Let me check my messages to see if I received that security code.","position":10,"audioStartSeconds":40.87079166666667,"audioEndSeconds":45.16204166666667},{"speaker":"B","text":"Take your time while you look through your messages for the numbers.","position":11,"audioStartSeconds":45.36204166666667,"audioEndSeconds":49.253791666666665},{"speaker":"A","text":"I found the text message and the numbers are clearly visible on my screen.","position":12,"audioStartSeconds":49.45379166666667,"audioEndSeconds":54.2605},{"speaker":"B","text":"That is wonderful news so you will have no trouble getting inside the flat.","position":13,"audioStartSeconds":54.4605,"audioEndSeconds":59.06104166666667},{"speaker":"A","text":"Thank you very much for being so helpful and understanding about my late arrival.","position":14,"audioStartSeconds":59.261041666666664,"audioEndSeconds":64.32545833333333},{"speaker":"B","text":"You are very welcome and please send me a quick text when you are safely inside.","position":15,"audioStartSeconds":64.52545833333333,"audioEndSeconds":69.47379166666667},{"speaker":"A","text":"I will definitely send you a message as soon as I enter the apartment.","position":16,"audioStartSeconds":69.67379166666667,"audioEndSeconds":74.00570833333333}],"questions":[{"prompt":"Why is the guest calling the host?","options":["To cancel the booking.","To report a delayed arrival.","To ask for restaurant recommendations."],"answer":"B","evidenceSentence":1,"evidence":"my train is delayed","explanation":"Vị khách gọi điện để thông báo rằng chuyến tàu của họ bị hoãn và sẽ đến muộn hơn dự kiến."},{"prompt":"When does the guest expect to reach the apartment?","options":["Around nine o clock.","Around seven o clock.","Around ten o clock."],"answer":"A","evidenceSentence":4,"evidence":"arrive around nine o clock","explanation":"Vị khách dự kiến sẽ đến căn hộ vào khoảng chín giờ tối."},{"prompt":"Where will the host leave the keys?","options":["Under the welcome mat.","With a neighbor.","In a secure metal box."],"answer":"C","evidenceSentence":7,"evidence":"secure metal box","explanation":"Chủ nhà sẽ để chìa khóa trong một chiếc hộp kim loại an toàn cạnh lối vào."},{"prompt":"What does the guest need to open the key box?","options":["A physical metal key.","A four digit code.","A plastic swipe card."],"answer":"B","evidenceSentence":9,"evidence":"four digit code","explanation":"Vị khách cần mã bốn chữ số đã được gửi qua điện thoại để mở hộp chìa khóa."},{"prompt":"How does the guest confirm they have the required information?","options":["They remember it from last week.","They find it in a text message.","They ask a friend for help."],"answer":"B","evidenceSentence":12,"evidence":"found the text message","explanation":"Vị khách tìm thấy tin nhắn văn bản chứa các con số mã bảo mật trên màn hình điện thoại."},{"prompt":"What must the guest do after entering the apartment?","options":["Send a quick text to the host.","Call room service immediately.","Turn on the heating system."],"answer":"A","evidenceSentence":15,"evidence":"send me a quick text","explanation":"Chủ nhà yêu cầu vị khách gửi một tin nhắn nhanh khi đã ở an toàn bên trong."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
